function collect({previousState,tickets,newId,openId,reminderId,closeId}) {
  const ids=[newId,openId,reminderId,closeId];if(ids.some(x=>!Number.isSafeInteger(x)||x<1)||new Set(ids).size!==4)throw Error('Configure four distinct positive Zammad state IDs');
  if(previousState===null){if(tickets!==null)throw Error('Unexpected initial ticket page');return{state:{page:1,seen:[],counts:[0,0,0,0]},page:1,more:true,hasTickets:false,counts:[0,0,0,0]};}
  if(!previousState||!Number.isSafeInteger(previousState.page)||!Array.isArray(previousState.seen)||!Array.isArray(previousState.counts)||!Array.isArray(tickets))throw Error('Invalid Zammad page state');
  const seen=new Set(previousState.seen),counts=[...previousState.counts];for(const t of tickets){if(!t||!Number.isSafeInteger(t.id)||t.id<1||!Number.isSafeInteger(t.state_id)||seen.has(t.id))throw Error('Invalid or duplicate Zammad ticket');seen.add(t.id);const index=ids.indexOf(t.state_id);if(index!==-1)counts[index]++;}
  const state={page:previousState.page+1,seen:[...seen],counts};return{state,page:state.page,more:tickets.length>0,hasTickets:state.seen.length>0,counts};
}

const options={newId:1,openId:2,reminderId:3,closeId:7};let state=collect({previousState:null,tickets:null,...options}).state;state=collect({previousState:state,tickets:$input.all().map(x=>x.json),...options}).state;const result=collect({previousState:state,tickets:[],...options});return result.hasTickets?[{json:{counts:result.counts}}]:[];
